<?php
namespace App\Http\Controllers\Sales;use App\Http\Controllers\Controller;use App\Models\{CorporateAccount,EventVenue,HotelEvent,TravelAgent};use Illuminate\Http\Request;use Illuminate\Support\Str;
class EventController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('sales.events',['venues'=>EventVenue::where('property_id',$p)->get(),'companies'=>CorporateAccount::where('property_id',$p)->where('status','active')->get(),'agents'=>TravelAgent::where('property_id',$p)->where('status','active')->get(),'events'=>HotelEvent::where('property_id',$p)->with('venue','company','agent')->orderBy('starts_at')->paginate(40)]);}public function venue(Request $r){$d=$r->validate(['name'=>'required|max:180','code'=>'required|max:30','capacity'=>'required|integer|min:1','base_rate'=>'nullable|numeric|min:0','description'=>'nullable|string']);EventVenue::create([...$d,'property_id'=>auth()->user()->property_id]);return back()->with('success','Event venue created.');}public function store(Request $r){$d=$r->validate(['title'=>'required|max:180','event_type'=>'required|max:50','event_venue_id'=>'nullable|exists:event_venues,id','corporate_account_id'=>'nullable|exists:corporate_accounts,id','travel_agent_id'=>'nullable|exists:travel_agents,id','contact_name'=>'nullable|max:120','contact_phone'=>'nullable|max:50','contact_email'=>'nullable|email','starts_at'=>'required|date','ends_at'=>'required|date|after:starts_at','expected_guests'=>'required|integer|min:1','estimated_total'=>'nullable|numeric|min:0','deposit_required'=>'nullable|numeric|min:0','requirements'=>'nullable|string']);if(!empty($d['event_venue_id'])){$clash=HotelEvent::where('property_id',auth()->user()->property_id)->where('event_venue_id',$d['event_venue_id'])->whereNotIn('status',['cancelled'])->where('starts_at','<',$d['ends_at'])->where('ends_at','>',$d['starts_at'])->exists();if($clash)return back()->withErrors(['event_venue_id'=>'Venue is already booked during this period.'])->withInput();}$e=HotelEvent::create([...$d,'property_id'=>auth()->user()->property_id,'reference'=>'EVT-'.now()->format('YmdHis').'-'.Str::upper(Str::random(4)),'created_by'=>auth()->id()]);return back()->with('success','Event '.$e->reference.' created.');}}
